// MARK: - Errors

/// Error enum for DevOpsGuru
public struct DevOpsGuruErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        ///  You don't have permissions to perform the requested operation. The user or role that
        /// 			is making the request must have at least one IAM permissions policy attached that grants
        /// 			the required permissions. For more information, see Access Management in the
        /// 				IAM User Guide.
        case accessDeniedException
        ///  An exception that is thrown when a conflict occurs.
        case conflictException(DevOpsGuru.ConflictException)
        /// An internal failure in an Amazon service occurred.
        case internalServerException(DevOpsGuru.InternalServerException)
        /// A requested resource could not be found
        case resourceNotFoundException(DevOpsGuru.ResourceNotFoundException)
        /// The request contains a value that exceeds a maximum quota.
        case serviceQuotaExceededException
        /// The request was denied due to a request throttling.
        case throttlingException(DevOpsGuru.ThrottlingException)
        ///  Contains information about data passed in to a field during a request that is not
        /// 			valid.
        case validationException(DevOpsGuru.ValidationException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "AccessDeniedException": self.error = .accessDeniedException
        case "ConflictException":
            let context = try singleValueContainer.decode(DevOpsGuru.ConflictException.self)
            self.error = .conflictException(context)
        case "InternalServerException":
            let context = try singleValueContainer.decode(DevOpsGuru.InternalServerException.self)
            self.error = .internalServerException(context)
        case "ResourceNotFoundException":
            let context = try singleValueContainer.decode(DevOpsGuru.ResourceNotFoundException.self)
            self.error = .resourceNotFoundException(context)
        case "ServiceQuotaExceededException": self.error = .serviceQuotaExceededException
        case "ThrottlingException":
            let context = try singleValueContainer.decode(DevOpsGuru.ThrottlingException.self)
            self.error = .throttlingException(context)
        case "ValidationException":
            let context = try singleValueContainer.decode(DevOpsGuru.ValidationException.self)
            self.error = .validationException(context)
        default:
            throw responseError
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .accessDeniedException: "AccessDeniedException"
        case .conflictException: "ConflictException"
        case .internalServerException: "InternalServerException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceQuotaExceededException: "ServiceQuotaExceededException"
        case .throttlingException: "ThrottlingException"
        case .validationException: "ValidationException"
        }
    }
}
